// ================= НАСТРОЙКИ =================
// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.
const config = {
  // ---- кто пишет ----
  company: 'Название компании',
  sender_name: 'Анна, финансовый отдел',
  payment_details: 'Оплатить можно по реквизитам в счёте или по ссылке: https://example.com/pay',
  timezone_offset_hours: 2,

  // ---- где данные ----
  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',   // листы Invoices, Drafts, Activity

  // ---- кто одобряет ----
  // ID Telegram-чатов, которым можно нажимать кнопки и писать команды. Первый получает черновики и отчёт.
  approver_chat_ids: ['ВСТАВЬТЕ_ID_ЧАТА'],

  // ---- письма ----
  email: {
    from: 'Финансовый отдел <billing@example.com>',
    reply_to: 'billing@example.com',
  },

  // ---- последовательность напоминаний ----
  // day — сколько дней просрочки, tone — тон письма. Шаг отправляется, только если предыдущий уже ушёл.
  sequence: [
    { day: 1, tone: 'friendly' },    // дружеское: «возможно, письмо потерялось»
    { day: 7, tone: 'firm' },        // деловое: конкретная просьба и срок
    { day: 14, tone: 'escalate' },   // настойчивое: предложить созвон, график платежей
    { day: 30, tone: 'final' },      // последнее: что будет дальше — только то, что разрешено ниже
  ],
  min_gap_days: 3,                   // не чаще одного письма по счёту за столько дней
  max_drafts_per_run: 20,

  // ---- риск ----
  high_amount: 5000,                 // счета от этой суммы — выше риск

  // ---- что можно упоминать в письмах ----
  // По умолчанию письма не грозят: никаких судов, коллекторов, штрафов.
  allow_late_fee: false,             // true — можно упомянуть пени из договора
  late_fee_text: '',                 // точная формулировка из договора, например «0,1% за день просрочки по п. 5.2»
  allow_collection: false,           // true — в последнем письме можно упомянуть передачу долга агентству
  collection_text: '',               // точная формулировка

  // ---- предпросмотр для evals ----
  preview_token: '',                 // пусто — вебхук предпросмотра выключен
};

return [{ json: { config, input: $input.first().json } }];

// Plan Invoices: какие счета пора напомнить сегодня и каким по счёту письмом.
// ---- shared text helpers (inlined into Code nodes by the builder) ----
const STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));

function stem(word) {
  let w = word.toLowerCase().replace(/ё/g, 'е');
  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);
  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');
  return w.slice(0, 6);
}

function terms(text) {
  return (String(text).toLowerCase().match(/[\p{L}\p{N}]+/gu) || [])
    .filter((w) => w.length > 1 && !STOP.has(w))
    .map(stem)
    .filter((w) => w.length > 1);
}

function escapeHtml(text) {
  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function sheetRows(values) {
  const [head = [], ...rows] = values || [];
  const keys = head.map((h) => String(h).trim().toLowerCase());
  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));
}

// ---- счета: даты, правила остановки, риск по правилам ----
const DAY = 86400000;

function today(config, now) {
  return new Date(now + config.timezone_offset_hours * 3600000).toISOString().slice(0, 10);
}

function parseDate(v) {
  const s = String(v || '').trim();
  let m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = /^(\d{1,2})[./](\d{1,2})[./](\d{4})$/.exec(s);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return '';
}

function daysBetween(a, b) {
  return Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / DAY);
}

function num(v) {
  const n = parseFloat(String(v ?? '').replace(/[\s ]/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : 0;
}

function yesish(v) {
  return /^(1|true|yes|да|y)$/i.test(String(v ?? '').trim());
}

function fmtAmount(n) {
  const [i, d] = n.toFixed(2).split('.');
  return i.replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + (d === '00' ? '' : ',' + d);
}

/** Invoices: invoice_id | client | contact_name | email | amount | currency | issued | due | status | paid_at | promise_date | disputed | paused | last_contact | stage | notes */
const INVOICE_COLS = ['invoice_id', 'client', 'contact_name', 'email', 'amount', 'currency', 'issued', 'due', 'status', 'paid_at', 'promise_date', 'disputed', 'paused', 'last_contact', 'stage', 'notes'];

function invoices(values) {
  return sheetRows(values).filter((r) => r.invoice_id).map((r) => ({
    ...r,
    amount_n: num(r.amount),
    due_d: parseDate(r.due),
    paid_d: parseDate(r.paid_at),
    promise_d: parseDate(r.promise_date),
    last_d: parseDate(r.last_contact),
    stage_n: Number(r.stage || 0),
    closed: /^(paid|оплачен|cancelled|отменён|отменен|written.off|списан)/i.test(r.status || '') || Boolean(parseDate(r.paid_at)),
  }));
}

function invoiceRow(inv) {
  return INVOICE_COLS.map((k) => String(inv[k] ?? ''));
}

/** Why an invoice must not be chased right now; '' — can be chased. */
function stopReason(inv, day) {
  if (inv.closed) return 'оплачен или закрыт';
  if (yesish(inv.disputed)) return 'клиент оспаривает счёт';
  if (yesish(inv.paused)) return 'напоминания на паузе';
  if (inv.promise_d && inv.promise_d >= day) return `клиент обещал оплатить до ${inv.promise_d}`;
  if (!inv.email) return 'нет email';
  if (!inv.due_d) return 'нет даты оплаты';
  return '';
}

/** Deterministic risk: low / medium / high with reasons in words. */
function ruleRisk(inv, all, day, config) {
  const reasons = [];
  let score = 0;
  const overdue = daysBetween(inv.due_d, day);
  if (overdue > 60) { score += 3; reasons.push(`просрочка ${overdue} дн.`); }
  else if (overdue > 30) { score += 2; reasons.push(`просрочка ${overdue} дн.`); }
  else if (overdue > 7) { score += 1; reasons.push(`просрочка ${overdue} дн.`); }
  if (inv.amount_n >= config.high_amount) { score += 1; reasons.push(`крупная сумма (${fmtAmount(inv.amount_n)} ${inv.currency})`); }
  const late = all.filter((x) => x.client === inv.client && x.invoice_id !== inv.invoice_id && x.paid_d && x.due_d && x.paid_d > x.due_d).length;
  if (late >= 2) { score += 1; reasons.push(`клиент уже ${late} раза платил с опозданием`); }
  if (inv.promise_d && inv.promise_d < day) { score += 2; reasons.push(`обещание оплатить до ${inv.promise_d} не выполнено`); }
  if (inv.stage_n >= 3) { score += 1; reasons.push(`уже ${inv.stage_n} напоминания без оплаты`); }
  const risk = score >= 4 ? 'high' : score >= 2 ? 'medium' : 'low';
  return { risk, reasons: reasons.length ? reasons : ['небольшая просрочка, раньше проблем не было'], overdue, late_count: late };
}

const RISK_ORDER = { low: 0, medium: 1, high: 2 };

const TONE_RU = { friendly: 'дружеский', firm: 'деловой', escalate: 'настойчивый', final: 'последнее напоминание' };

/** What the model sees about one invoice. */
function factsText(p, config) {
  const allowed = [];
  if (config.allow_late_fee && config.late_fee_text) allowed.push(`пени по договору: ${config.late_fee_text}`);
  if (config.allow_collection && config.collection_text && p.final_step) allowed.push(`передача долга: ${config.collection_text}`);
  return [
    `Счёт: ${p.invoice_id}`,
    `Клиент: ${p.client}${p.contact_name ? ', контакт: ' + p.contact_name : ''}`,
    `Сумма: ${p.amount_text}`,
    `Выставлен: ${p.issued || 'не указано'}; срок оплаты: ${p.due}; просрочка: ${p.overdue} дн.`,
    `Письмо №${p.step} из ${config.sequence.length}, тон: ${p.tone} (${TONE_RU[p.tone] || p.tone})${p.final_step ? ', последнее в последовательности' : ''}`,
    p.broken_promise ? 'Клиент обещал оплатить к дате, которая уже прошла.' : '',
    p.late_count ? `Раньше клиент платил с опозданием: ${p.late_count} раз(а).` : 'Раньше просрочек по другим счетам не было.',
    `Риск по правилам: ${p.rule_risk} — ${p.rule_reasons.join('; ')}`,
    p.notes ? `Заметки менеджера: ${p.notes}` : 'Заметок нет.',
    allowed.length ? `Разрешено упомянуть дословно: ${allowed.join('; ')}` : 'Упоминать пени, суд, коллекторов и любые санкции нельзя.',
  ].filter(Boolean).join('\n');
}

const { config } = $('Config').first().json;
const day = today(config, Date.now());
const sheets = $input.first().json.valueRanges || [];
const all = invoices(sheets[0]?.values);
const drafts = sheetRows(sheets[1]?.values);
const waiting = new Set(drafts.filter((d) => ['pending', 'editing'].includes(d.status)).map((d) => d.invoice_id));

const plan = [];
for (const inv of all) {
  if (stopReason(inv, day)) continue;
  const overdue = daysBetween(inv.due_d, day);
  if (overdue < 1) continue;
  if (waiting.has(inv.invoice_id)) continue;                       // черновик уже ждёт решения
  if (inv.last_d && daysBetween(inv.last_d, day) < config.min_gap_days) continue;
  const step = config.sequence[inv.stage_n];
  if (!step || overdue < step.day) continue;                       // все шаги пройдены или рано
  const risk = ruleRisk(inv, all, day, config);
  plan.push({
    mode: 'monitor', invoice_id: inv.invoice_id, row: inv._row, client: inv.client, contact_name: inv.contact_name, email: inv.email,
    amount: inv.amount_n, amount_text: `${fmtAmount(inv.amount_n)} ${inv.currency}`.trim(), currency: inv.currency,
    issued: parseDate(inv.issued), due: inv.due_d, overdue, step: inv.stage_n + 1, tone: step.tone,
    final_step: inv.stage_n + 1 === config.sequence.length, broken_promise: Boolean(inv.promise_d && inv.promise_d < day),
    notes: String(inv.notes || '').slice(0, 500), rule_risk: risk.risk, rule_reasons: risk.reasons, late_count: risk.late_count,
  });
  plan[plan.length - 1].facts = factsText(plan[plan.length - 1], config);
}
plan.sort((a, b) => RISK_ORDER[b.rule_risk] - RISK_ORDER[a.rule_risk] || b.overdue - a.overdue || b.amount - a.amount);
return plan.slice(0, config.max_drafts_per_run).map((p) => ({ json: p }));

