// ---- счета: даты, правила остановки, риск по правилам ----
const DAY = 86400000;

function today(config, now) {
  return new Date(now + config.timezone_offset_hours * 3600000).toISOString().slice(0, 10);
}

function parseDate(v) {
  const s = String(v || '').trim();
  let m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = /^(\d{1,2})[./](\d{1,2})[./](\d{4})$/.exec(s);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return '';
}

function daysBetween(a, b) {
  return Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / DAY);
}

function num(v) {
  const n = parseFloat(String(v ?? '').replace(/[\s ]/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : 0;
}

function yesish(v) {
  return /^(1|true|yes|да|y)$/i.test(String(v ?? '').trim());
}

function fmtAmount(n) {
  const [i, d] = n.toFixed(2).split('.');
  return i.replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + (d === '00' ? '' : ',' + d);
}

/** Invoices: invoice_id | client | contact_name | email | amount | currency | issued | due | status | paid_at | promise_date | disputed | paused | last_contact | stage | notes */
const INVOICE_COLS = ['invoice_id', 'client', 'contact_name', 'email', 'amount', 'currency', 'issued', 'due', 'status', 'paid_at', 'promise_date', 'disputed', 'paused', 'last_contact', 'stage', 'notes'];

function invoices(values) {
  return sheetRows(values).filter((r) => r.invoice_id).map((r) => ({
    ...r,
    amount_n: num(r.amount),
    due_d: parseDate(r.due),
    paid_d: parseDate(r.paid_at),
    promise_d: parseDate(r.promise_date),
    last_d: parseDate(r.last_contact),
    stage_n: Number(r.stage || 0),
    closed: /^(paid|оплачен|cancelled|отменён|отменен|written.off|списан)/i.test(r.status || '') || Boolean(parseDate(r.paid_at)),
  }));
}

function invoiceRow(inv) {
  return INVOICE_COLS.map((k) => String(inv[k] ?? ''));
}

/** Why an invoice must not be chased right now; '' — can be chased. */
function stopReason(inv, day) {
  if (inv.closed) return 'оплачен или закрыт';
  if (yesish(inv.disputed)) return 'клиент оспаривает счёт';
  if (yesish(inv.paused)) return 'напоминания на паузе';
  if (inv.promise_d && inv.promise_d >= day) return `клиент обещал оплатить до ${inv.promise_d}`;
  if (!inv.email) return 'нет email';
  if (!inv.due_d) return 'нет даты оплаты';
  return '';
}

/** Deterministic risk: low / medium / high with reasons in words. */
function ruleRisk(inv, all, day, config) {
  const reasons = [];
  let score = 0;
  const overdue = daysBetween(inv.due_d, day);
  if (overdue > 60) { score += 3; reasons.push(`просрочка ${overdue} дн.`); }
  else if (overdue > 30) { score += 2; reasons.push(`просрочка ${overdue} дн.`); }
  else if (overdue > 7) { score += 1; reasons.push(`просрочка ${overdue} дн.`); }
  if (inv.amount_n >= config.high_amount) { score += 1; reasons.push(`крупная сумма (${fmtAmount(inv.amount_n)} ${inv.currency})`); }
  const late = all.filter((x) => x.client === inv.client && x.invoice_id !== inv.invoice_id && x.paid_d && x.due_d && x.paid_d > x.due_d).length;
  if (late >= 2) { score += 1; reasons.push(`клиент уже ${late} раза платил с опозданием`); }
  if (inv.promise_d && inv.promise_d < day) { score += 2; reasons.push(`обещание оплатить до ${inv.promise_d} не выполнено`); }
  if (inv.stage_n >= 3) { score += 1; reasons.push(`уже ${inv.stage_n} напоминания без оплаты`); }
  const risk = score >= 4 ? 'high' : score >= 2 ? 'medium' : 'low';
  return { risk, reasons: reasons.length ? reasons : ['небольшая просрочка, раньше проблем не было'], overdue, late_count: late };
}

const RISK_ORDER = { low: 0, medium: 1, high: 2 };

const TONE_RU = { friendly: 'дружеский', firm: 'деловой', escalate: 'настойчивый', final: 'последнее напоминание' };

/** What the model sees about one invoice. */
function factsText(p, config) {
  const allowed = [];
  if (config.allow_late_fee && config.late_fee_text) allowed.push(`пени по договору: ${config.late_fee_text}`);
  if (config.allow_collection && config.collection_text && p.final_step) allowed.push(`передача долга: ${config.collection_text}`);
  return [
    `Счёт: ${p.invoice_id}`,
    `Клиент: ${p.client}${p.contact_name ? ', контакт: ' + p.contact_name : ''}`,
    `Сумма: ${p.amount_text}`,
    `Выставлен: ${p.issued || 'не указано'}; срок оплаты: ${p.due}; просрочка: ${p.overdue} дн.`,
    `Письмо №${p.step} из ${config.sequence.length}, тон: ${p.tone} (${TONE_RU[p.tone] || p.tone})${p.final_step ? ', последнее в последовательности' : ''}`,
    p.broken_promise ? 'Клиент обещал оплатить к дате, которая уже прошла.' : '',
    p.late_count ? `Раньше клиент платил с опозданием: ${p.late_count} раз(а).` : 'Раньше просрочек по другим счетам не было.',
    `Риск по правилам: ${p.rule_risk} — ${p.rule_reasons.join('; ')}`,
    p.notes ? `Заметки менеджера: ${p.notes}` : 'Заметок нет.',
    allowed.length ? `Разрешено упомянуть дословно: ${allowed.join('; ')}` : 'Упоминать пени, суд, коллекторов и любые санкции нельзя.',
  ].filter(Boolean).join('\n');
}

const { config } = $('Config').first().json;
const plans = ($('Preview Plan').isExecuted ? $('Preview Plan') : $('Plan Invoices')).all().map((i) => i.json);
const answers = $input.all().map((i) => i.json);

// \b в JS не видит границу кириллического слова — поэтому (?<![а-яё]) и (?![а-яё])
const THREATS = [/(?<![а-яё])суд(?![а-яё])|(?<![а-яё])судеб|(?<![а-яё])иск(?![а-яё])|(?<![а-яё])исков|юрист|адвокат|коллектор|арбитраж|прокурат|полици|штраф|(?<![а-яё])пен(я|и|ю|ей|ям)(?![а-яё])|неустойк|кредитн[а-я]* истори|санкци|court|lawsuit|lawyer|attorney|collection agenc|debt collector|penalt|late fee|credit score/i];
const SHAMING = /(игнорир|нарушил|безответствен|недобросовест|вы обязаны немедленно)/i;
const DISCOUNT = /(скидк|рассрочк|списываем|прощаем|discount|write.?off)/i;

function parse(text) {
  const t = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const s = t.indexOf('{');
  const e = t.lastIndexOf('}');
  if (s < 0 || e <= s) return null;
  try { return JSON.parse(t.slice(s, e + 1)); } catch { return null; }
}

function amountIn(body, p) {
  const digits = String(body).replace(/[\s ]/g, '');
  const whole = String(Math.trunc(p.amount));
  return digits.includes(whole) || digits.includes(fmtAmount(p.amount).replace(/\s/g, ''));
}

function template(p) {
  const hi = p.contact_name ? `${p.contact_name}, добрый день!` : 'Добрый день!';
  const t = {
    friendly: `Напоминаем о счёте ${p.invoice_id} на ${p.amount_text}: срок оплаты был ${p.due}. Возможно, письмо затерялось — подскажите, пожалуйста, всё ли в порядке и когда планируете оплату?`,
    firm: `Счёт ${p.invoice_id} на ${p.amount_text} просрочен на ${p.overdue} дн. (срок был ${p.due}). Просим оплатить его или сообщить дату оплаты в ответ на это письмо.`,
    escalate: `Счёт ${p.invoice_id} на ${p.amount_text} не оплачен уже ${p.overdue} дн. Давайте найдём решение: можем созвониться и обсудить удобный график. Пожалуйста, ответьте в ближайшие дни.`,
    final: `Это последнее напоминание о счёте ${p.invoice_id} на ${p.amount_text}, срок оплаты которого истёк ${p.due}. Пожалуйста, оплатите счёт или свяжитесь с нами, чтобы договориться.`,
  }[p.tone] || '';
  return { subject: `Счёт ${p.invoice_id}: напоминание об оплате`, body: `${hi}\n\n${t}` };
}

const allowedText = [config.allow_late_fee && config.late_fee_text, config.allow_collection && config.collection_text].filter(Boolean);

return plans.map((p, i) => {
  const flags = [];
  const a = parse(answers[i]?.text ?? answers[i]?.output);
  let risk = p.rule_risk;
  let reasons = [...p.rule_reasons];
  let subject = '';
  let body = '';
  if (!a) flags.push('template:not_json');
  else {
    if (['low', 'medium', 'high'].includes(a.risk)) {
      if (RISK_ORDER[a.risk] > RISK_ORDER[risk]) {
        risk = a.risk;
        flags.push('risk_raised_by_model');
      }
      if (Array.isArray(a.reasons)) reasons = [...reasons, ...a.reasons.map(String).slice(0, 4).map((r) => 'модель: ' + r.slice(0, 160))];
    } else flags.push('bad_risk');
    subject = String(a.subject || '').replace(/\s+/g, ' ').trim();
    body = String(a.body || '').trim();
    let why = '';
    if (!subject || subject.length > 120) why = 'subject';
    else if (!body || body.length < 40) why = 'empty';
    else if (body.length > 2000) why = 'too_long';
    else if (!body.includes(p.invoice_id)) why = 'no_invoice_id';
    else if (!amountIn(body, p)) why = 'no_amount';
    else {
      // разрешённую формулировку из Config вырезаем перед проверкой — остальное грозить не должно
      let check = body;
      for (const t of allowedText) check = check.split(t).join('');
      if (THREATS.some((r) => r.test(check + ' ' + subject))) why = 'threat';
      else if (SHAMING.test(body)) why = 'shaming';
      else if (DISCOUNT.test(body)) why = 'discount';
      else if (/https?:\/\/|www\./i.test(body)) why = 'link';
    }
    if (why) flags.push('template:' + why);
  }
  if (flags.some((f) => f.startsWith('template:'))) ({ subject, body } = template(p));
  const full = [body, '', config.payment_details, '', 'С уважением,', config.sender_name, config.company].join('\n');
  const draft_id = 'D-' + Date.now().toString(36).toUpperCase().slice(-5) + i.toString(36).toUpperCase() + Math.floor(Math.random() * 36 ** 2).toString(36).toUpperCase().padStart(2, '0');
  return { json: { ...p, draft_id, risk, reasons, subject, body: full, flags } };
});

// Draft Rows: черновики — в лист Drafts одной записью.
// Drafts: draft_id | created | invoice_id | step | tone | risk | reasons | to | subject | body | status | decided_at | decided_by
const now = new Date().toISOString();
const rows = $input.all().map(({ json: d }) => [d.draft_id, now, d.invoice_id, String(d.step), d.tone, d.risk, d.reasons.join('; '),
  d.email, d.subject, d.body, 'pending', '', '']);
return [{ json: { rows } }];

